page.css:
/* ==========================================================================
   GLOBAL SHELL. Header, navigation, Quick Quote and the mobile action bar all
   live inside this one <header> with this one stylesheet, deliberately: the
   site importer files a single element and its nested <style> as one scoped
   part, and every :checked ~ sibling selector below has to stay inside it.
   No JavaScript anywhere. See the developer handoff, section 4.
   ========================================================================== */
.site-header *,.site-header *::before,.site-header *::after{box-sizing:border-box}
.site-header{
  --h-plaster:#F7F6F2; --h-plaster2:#EFEDE6; --h-line:#DFDCD2;
  --h-char:#202124; --h-char2:#2B2D31; --h-text:#26282C; --h-muted:#5E6167;
  --h-red:#E1252D; --h-red-ink:#B31D23; --h-red-tint:#FBEBEC;
  --h-font:"Inter",system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  position:sticky; top:0; z-index:900; font-family:var(--h-font);
  background:var(--h-plaster); border-bottom:1px solid var(--h-line);
  box-shadow:0 1px 0 rgba(20,24,28,.03), 0 10px 30px -22px rgba(20,24,28,.35);
}
.site-header::before{content:"";position:absolute;inset:0 0 auto 0;height:3px;background:var(--h-red)}
.site-header a{text-decoration:none;color:inherit}
.site-header ul{list-style:none;margin:0;padding:0}

.hdr-bar{max-width:1280px;margin:0 auto;padding:0 22px;display:flex;align-items:stretch;gap:18px;min-height:82px}
.hdr-brand{display:flex;flex-direction:column;justify-content:center;gap:3px;flex:0 1 auto;min-width:0}
.hdr-logo{display:flex;align-items:center;flex:0 1 auto;min-width:0;padding:0}
.hdr-desc{
  margin:0;font-size:8.8px;font-weight:800;letter-spacing:.098em;text-transform:uppercase;
  color:var(--h-muted);white-space:nowrap;
}
.hdr-desc span{color:var(--h-red-ink);margin:0 3px}
@media (max-width:1040px){.hdr-desc{display:none}}
.hdr-logo img{height:52px;width:auto;display:block}
.hdr-logo .lg-compact{display:none}

.hdr-navwrap{display:contents}
.hdr-nav{margin-left:auto;display:flex;align-items:stretch}
.hdr-nav > li{position:relative;display:flex;align-items:stretch}
.nav-top{
  display:flex;align-items:center;gap:6px;padding:0 14px;white-space:nowrap;
  font-size:15px;font-weight:700;letter-spacing:.004em;color:var(--h-text);
  border-bottom:3px solid transparent;position:relative;
}
.nav-top .chev{width:9px;height:9px;fill:none;stroke:var(--h-muted);stroke-width:2.4;stroke-linecap:round;
  stroke-linejoin:round;transition:transform .18s ease;flex:0 0 auto;margin-top:1px}
.hdr-nav > li:hover .nav-top,.hdr-nav > li:focus-within .nav-top{color:var(--h-red-ink)}
.hdr-nav > li:hover .nav-top .chev,.hdr-nav > li:focus-within .nav-top .chev{transform:rotate(180deg);stroke:var(--h-red-ink)}
.nav-top:hover,.nav-top:focus-visible{border-bottom-color:var(--h-red)}

/* ---- dropdown panels. No gap between trigger and panel, so no hover dead zone ---- */
.menu{
  position:absolute;top:100%;left:50%;transform:translate(-50%,8px);
  background:#fff;border:1px solid var(--h-line);border-top:3px solid var(--h-red);
  border-radius:0 0 14px 14px;box-shadow:0 30px 60px -22px rgba(20,24,28,.38);
  opacity:0;visibility:hidden;pointer-events:none;transition:opacity .16s ease,transform .16s ease,visibility .16s;
  z-index:10;
}
.hdr-nav > li:hover > .menu,.hdr-nav > li:focus-within > .menu{
  opacity:1;visibility:visible;pointer-events:auto;transform:translate(-50%,0);
}
/* the services panel is anchored to its trigger's left edge, not centred on it,
   because a 740px panel centred on a left-hand nav item runs off screen near 1041px */
.hdr-nav > li:hover > .menu-svc,.hdr-nav > li:focus-within > .menu-svc{transform:translate(-50%,0)}
.menu-svc{
  position:fixed;top:75px;left:50%;width:min(1160px,calc(100vw - 44px));
  display:grid;grid-template-columns:1fr 250px;transform:translate(-50%,8px);
  max-height:calc(100dvh - 91px);overflow:auto;
}
.menu-cols{display:grid;gap:0;padding:18px 12px 18px 16px}
.menu-svc .menu-cols{grid-template-columns:repeat(4,1fr);padding:18px 8px 18px 12px}
.menu-svc .menu-col{padding:0 8px;border-left:1px solid var(--h-line)}
.menu-svc .menu-col:first-child{border-left:0}
.menu-svc .menu-group{padding:0;border-left:0}
.menu-svc .menu-group + .menu-group{margin-top:13px}
.menu-svc .menu-group a{padding:6px 8px;font-size:13.4px;line-height:1.34}
.menu-svc .menu-group--lead a{font-size:13.4px}
.menu-group{padding:0 10px;border-left:1px solid var(--h-line)}
.menu-group:first-child{border-left:0}
.menu-group .mg-t{
  margin:0 0 8px;padding:0 8px;font-size:11.4px;font-weight:800;letter-spacing:.14em;
  text-transform:uppercase;color:var(--h-muted);
}
.menu-group--lead .mg-t{color:var(--h-red-ink)}
.menu-group a{
  display:block;padding:7px 8px;border-radius:7px;font-size:14px;font-weight:600;color:var(--h-text);
  border-left:3px solid transparent;
}
.menu-group--lead a{font-size:14.6px}
.menu-group a small{display:block;font-size:12.2px;font-weight:500;color:var(--h-muted);margin-top:1px;line-height:1.35}
.menu-group a:hover,.menu-group a:focus-visible{background:var(--h-plaster2);border-left-color:var(--h-red);color:var(--h-red-ink)}
.menu-group .all{margin-top:8px;border-top:1px solid var(--h-line);border-radius:0;padding-top:12px;font-weight:800;color:var(--h-red-ink)}
.menu-group .all:hover{background:transparent;border-left-color:transparent;text-decoration:underline}
.menu-list{padding:16px 14px 18px}
.menu-list a{
  display:block;padding:9px 14px;border-radius:8px;font-size:14.6px;font-weight:600;color:var(--h-text);
  border-left:3px solid transparent;
}
.menu-list a small{display:block;font-size:12.6px;font-weight:500;color:var(--h-muted);margin-top:2px;line-height:1.35}
.menu-list a:hover,.menu-list a:focus-visible{background:var(--h-plaster2);border-left-color:var(--h-red);color:var(--h-red-ink)}
.menu-list .all{margin-top:6px;border-top:1px solid var(--h-line);border-radius:0;padding-top:13px;font-weight:800;color:var(--h-red-ink)}
.menu-list .all:hover{background:transparent;border-left-color:transparent;text-decoration:underline}
.menu-aside{background:var(--h-char);color:#C9D0D8;padding:22px 22px 24px;border-radius:0 0 11px 0;display:flex;flex-direction:column}
.menu-aside .aside-t{color:#fff;font-size:1.02rem;margin:0 0 8px;letter-spacing:-.01em;line-height:1.25}
.menu-aside p{margin:0 0 16px;font-size:13.4px;line-height:1.55;color:#AEB7C1}
.menu-aside .mini{
  display:inline-flex;align-items:center;justify-content:center;gap:8px;
  background:var(--h-red-ink);color:#fff;font-weight:800;font-size:13.4px;padding:11px 15px;border-radius:8px;
  border:2px solid var(--h-red-ink);
}
.menu-aside .mini:hover,.menu-aside .mini:focus-visible{background:var(--h-red);border-color:var(--h-red)}
.menu-aside .menu-tel{
  margin-top:auto;padding-top:18px;display:flex;align-items:center;gap:9px;
  color:#fff;font-weight:800;font-size:14.6px;border-top:1px solid rgba(255,255,255,.14);
}
.menu-aside .menu-tel svg{width:15px;height:15px;fill:var(--h-red);flex:0 0 auto}
.menu-aside .menu-tel span{display:block;font-size:11.6px;font-weight:700;letter-spacing:.13em;
  text-transform:uppercase;color:#AEB7C1;margin-bottom:2px}
.menu-areas{position:fixed;top:75px;left:50%;width:min(860px,calc(100vw - 44px));
  display:grid;grid-template-columns:1fr 262px;transform:translate(-50%,8px);
  max-height:calc(100dvh - 91px);overflow:auto}
.menu-areas .menu-cols{grid-template-columns:1fr 1fr;padding:18px 12px 18px 16px}
.menu-areas .menu-list{padding:14px 12px 16px}
.menu-areas .menu-list a{break-inside:avoid}
.menu-areas .menu-list .all{column-span:all}

.hdr-actions{display:flex;align-items:center;gap:12px;flex:0 0 auto;padding:13px 0}
.hdr-phone{display:inline-flex;align-items:center;gap:9px;font-weight:800;font-size:15px;padding:10px 12px;
  border-radius:8px;white-space:nowrap;color:var(--h-text)}
.hdr-phone:hover,.hdr-phone:focus-visible{color:var(--h-red-ink);background:var(--h-red-tint)}
.hdr-phone svg{width:16px;height:16px;fill:var(--h-red-ink);flex:0 0 auto}
.site-header a.hdr-cta{
  background:var(--h-red-ink);color:#fff;font-weight:800;font-size:14.6px;letter-spacing:.01em;
  padding:13px 22px;border-radius:9px;white-space:nowrap;border:2px solid var(--h-red-ink);
  transition:background .15s ease,border-color .15s ease;
}
.site-header a.hdr-cta:hover,.site-header a.hdr-cta:focus-visible{background:var(--h-red);border-color:var(--h-red);color:#fff}
.hdr-burger{display:none}
.nav-tg{display:none}
.acc-tg,.acc-btn{display:none}
/* visually hidden but focusable: this checkbox IS the quick quote control */
.qq-tab:focus-visible,.mbar .quote:focus-visible{outline:3px solid var(--h-char);outline-offset:3px}
/* the close target: fixed and already in view, so following it never scrolls the page */
.qq-anchor{position:fixed;top:0;left:0;width:1px;height:1px;overflow:hidden;pointer-events:none}
.site-header a:focus-visible,.site-header label:focus-visible,.site-header button:focus-visible,
.site-header input:focus-visible{outline:3px solid var(--h-char);outline-offset:2px;border-radius:6px}

/* ==================== QUICK QUOTE ==================== */
.qq-dock{position:fixed;right:0;top:50%;transform:translateY(-50%);z-index:880;pointer-events:none}
.site-header a.qq-tab{
  pointer-events:auto;cursor:pointer;display:block;position:relative;
  background:var(--h-red-ink);color:#fff;border-radius:12px 0 0 12px;
  padding:26px 13px 26px 15px;box-shadow:-10px 12px 34px -10px rgba(20,24,28,.55);
  transition:padding-right .18s ease,background .18s ease;
}
.qq-tab::before{content:"";position:absolute;left:0;top:10px;bottom:10px;width:4px;border-radius:4px;background:var(--h-red)}
.qq-tab span{writing-mode:vertical-rl;transform:rotate(180deg);display:flex;align-items:center;gap:11px;
  font-weight:800;font-size:13px;letter-spacing:.15em;text-transform:uppercase;white-space:nowrap}
.qq-tab svg{width:16px;height:16px;fill:#fff;transform:rotate(90deg);flex:0 0 auto}
.site-header a.qq-tab:hover,.site-header a.qq-tab:focus-visible{padding-right:19px;background:var(--h-red);color:#fff}
.qq-panel:target ~ .qq-dock{opacity:0;pointer-events:none}
/* once open, the dock is hidden, so the focus ring moves to the close control */
.qq-x:focus-visible{outline:3px solid #fff;outline-offset:3px}

.qq-scrim{position:fixed;inset:0;z-index:940;background:rgba(14,18,22,.58);opacity:0;pointer-events:none;
  transition:opacity .3s ease;cursor:pointer}
.qq-panel:target ~ .qq-scrim{opacity:1;pointer-events:auto}

.qq-panel{
  position:fixed;top:0;right:0;bottom:0;z-index:950;width:min(452px,100%);
  background:var(--h-plaster);color:var(--h-text);border-left:3px solid var(--h-red);
  box-shadow:-40px 0 80px -30px rgba(14,18,22,.6);
  overflow-y:auto;overscroll-behavior:contain;
  transform:translateX(100%);visibility:hidden;
  transition:transform .34s cubic-bezier(.22,.8,.24,1),visibility .34s;
}
.qq-panel:target{transform:none;visibility:visible}
.qq-head{background:var(--h-char);color:#C9D0D8;padding:26px 26px 24px;position:relative}
.qq-head .qq-t{color:#fff;margin:0 0 9px;font-size:1.42rem;letter-spacing:-.018em;line-height:1.2}
.qq-head p{margin:0;font-size:14.2px;line-height:1.6;color:#AEB7C1}
.qq-head .qq-call{display:inline-flex;align-items:center;gap:9px;margin-top:17px;color:#fff;font-weight:800;font-size:15.4px}
.qq-head .qq-call svg{width:16px;height:16px;fill:var(--h-red)}
.qq-head .qq-call:hover,.qq-head .qq-call:focus-visible{color:var(--h-red)}
.site-header a.qq-x{position:absolute;top:16px;right:16px;width:42px;height:42px;border-radius:10px;cursor:pointer;
  background:rgba(255,255,255,.09);display:flex;align-items:center;justify-content:center}
.qq-x svg{width:17px;height:17px;stroke:#fff;stroke-width:2.4;fill:none;stroke-linecap:round}
.site-header a.qq-x:hover,.site-header a.qq-x:focus-visible{background:var(--h-red)}
.qq-body{padding:24px 26px 34px}
.qq-body .fld{margin-bottom:14px}
.qq-body label{display:block;font-size:13px;font-weight:700;margin-bottom:6px;color:var(--h-char)}
.qq-body .opt{font-weight:500;color:var(--h-muted)}
.qq-body input,.qq-body select,.qq-body textarea{
  width:100%;font-family:var(--h-font);font-size:16px;color:var(--h-text);background:#fff;
  border:1.5px solid #9A9284;border-radius:8px;padding:12px 13px;line-height:1.4;min-height:48px;
}
.qq-body textarea{min-height:84px;resize:vertical}
.qq-body select{appearance:none;padding-right:38px;background-repeat:no-repeat;background-position:right 13px center;
  background-size:15px;background-image:url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'%3E%3Cpath fill='%235C6570' d='M8 11.2 2.8 6l1.1-1.1L8 9l4.1-4.1L13.2 6z'/%3E%3C/svg%3E")}
.qq-body input:focus,.qq-body select:focus,.qq-body textarea:focus{outline:3px solid var(--h-char);outline-offset:1px;border-color:var(--h-char)}
.qq-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.qq-send{
  width:100%;margin-top:6px;background:var(--h-red-ink);color:#fff;border:2px solid var(--h-red-ink);
  font-family:var(--h-font);font-weight:800;font-size:15.4px;padding:15px;border-radius:9px;cursor:pointer;min-height:52px;
}
.qq-send:hover,.qq-send:focus-visible{background:var(--h-red);border-color:var(--h-red)}
.qq-note{font-size:12.6px;color:var(--h-muted);text-align:center;margin:13px 0 0;line-height:1.5}
/* ---------- optional photo upload, shared by the drawer and the contact form ---------- */
.up{border:1.5px dashed var(--h-line, #9A9284);border-radius:10px;padding:14px 14px 13px;background:#FBFAF8}
.up.up--has{border-style:solid;border-color:var(--h-char, var(--char, #24282C));background:#fff}
.up-help{margin:0 0 10px;font-size:12.8px;line-height:1.5;color:var(--h-muted, var(--muted, #5C6570))}
.up-types{margin:8px 0 0;font-size:12.2px;color:var(--h-muted, var(--muted, #5C6570))}
.up-picked{margin:9px 0 0;font-size:13px;font-weight:700;color:var(--h-char, var(--char, #24282C));word-break:break-word}
.up-input{
  width:100%;font-family:var(--h-font, inherit);font-size:15px;
  color:var(--h-text, var(--text, #2E3338));background:#fff;
  border:1.5px solid var(--h-line, #9A9284);border-radius:8px;padding:9px 11px;line-height:1.4;min-height:48px;
}
.up-input::file-selector-button{
  font-family:var(--h-font, inherit);font-weight:800;font-size:13.4px;color:#fff;
  background:var(--h-char, var(--char, #24282C));
  border:0;border-radius:7px;padding:10px 14px;margin-right:12px;cursor:pointer;min-height:38px;
}
.up-input::file-selector-button:hover{background:var(--h-red-ink, var(--red-ink, #A3121B))}
.up-input:focus,.up-input:focus-visible{outline:3px solid var(--h-char, var(--char, #24282C));
  outline-offset:1px;border-color:var(--h-char, var(--char, #24282C))}
.up-input:invalid{border-color:var(--h-red-ink, var(--red-ink, #A3121B))}
.up-clear{
  margin-top:10px;font-family:var(--h-font, inherit);font-weight:800;font-size:13px;
  color:var(--h-red-ink, var(--red-ink, #A3121B));background:#fff;
  border:1.5px solid var(--h-red-ink, var(--red-ink, #A3121B));border-radius:7px;padding:9px 13px;cursor:pointer;min-height:40px;
}
.up-clear:hover,.up-clear:focus-visible{background:var(--h-red-ink, var(--red-ink, #A3121B));color:#fff}
.up-clear:focus-visible{outline:3px solid var(--h-char, var(--char, #24282C));outline-offset:2px}

/* when closed, nothing inside the drawer is reachable by keyboard */
.qq-panel:not(:target){visibility:hidden}
/* lock the page behind the drawer where the browser supports it */
body:has(.qq-panel:target){overflow:hidden}

/* back to top. an anchor, not a script: #pagetop is a sentinel at the top of the body */
.site-header a.to-top{
  position:fixed;left:18px;bottom:18px;z-index:880;
  width:46px;height:46px;border-radius:11px;
  background:var(--h-char);border:1px solid rgba(255,255,255,.16);
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 14px 30px -12px rgba(20,24,28,.6);
  transition:background .15s ease,border-color .15s ease;
}
.to-top svg{width:17px;height:17px;fill:#fff;transform:rotate(-90deg)}
.site-header a.to-top:hover,.site-header a.to-top:focus-visible{background:var(--h-red-ink);border-color:var(--h-red-ink)}
.qq-panel:target ~ .to-top{opacity:0;pointer-events:none}

/* mobile action bar */
.mbar{display:none}

@media (max-width:1120px){
  .nav-top{padding:0 11px;font-size:14.4px}
  .hdr-bar{gap:12px}
}
@media (max-width:1040px){
  .hdr-bar{min-height:70px;gap:12px;align-items:center}
  .hdr-logo .lg-full{display:none}
  .hdr-logo .lg-compact{display:block;height:40px}
  .nav-tg{
    display:block;position:absolute;width:1px;height:1px;margin:-1px;padding:0;border:0;
    overflow:hidden;clip-path:inset(50%);white-space:nowrap;
  }
  .hdr-nav{
    position:fixed;inset:70px 0 auto 0;flex-direction:column;align-items:stretch;
    background:var(--h-plaster);border-bottom:1px solid var(--h-line);
    max-height:calc(100dvh - 70px);overflow-y:auto;padding:6px 14px 22px;
    transform:translateY(-10px);opacity:0;visibility:hidden;pointer-events:none;
    transition:opacity .2s ease,transform .2s ease,visibility .2s;box-shadow:0 24px 40px -24px rgba(20,24,28,.4);
  }
  .nav-tg:checked ~ .hdr-bar .hdr-nav{transform:none;opacity:1;visibility:visible;pointer-events:auto}
  .hdr-nav > li{display:block;border-bottom:1px solid var(--h-line)}
  .hdr-nav > li:last-child{border-bottom:0}
  /* .site-header ul resets padding at higher specificity, so this must out-specify it:
     it keeps the last nav item clear of the sticky bottom bar when an accordion is open */
  .site-header .hdr-nav{padding-bottom:92px}
  .nav-top{padding:15px 10px;font-size:16.4px;border-bottom:0;justify-content:space-between}
  /* dropdowns become accordions, driven by their own checkbox */
  .menu{position:static;transform:none;opacity:1;visibility:visible;pointer-events:auto;
    width:auto;border:0;box-shadow:none;border-radius:0;display:none;background:transparent}
  .hdr-nav > li:hover > .menu,.hdr-nav > li:focus-within > .menu{transform:none}
  .acc-tg{display:block;position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%)}
  li:has(> .acc-btn) > .nav-top{display:none}
  .acc-btn{display:flex;
    align-items:center;justify-content:space-between;gap:10px;width:100%;cursor:pointer;
    padding:15px 10px;font-size:16.4px;font-weight:700;color:var(--h-text);
  }
  .acc-btn .chev{width:11px;height:11px;fill:none;stroke:var(--h-red-ink);stroke-width:2.6;
    stroke-linecap:round;stroke-linejoin:round;transition:transform .2s ease}
  .acc-tg:checked ~ .acc-btn{color:var(--h-red-ink)}
  .acc-tg:checked ~ .acc-btn .chev{transform:rotate(180deg)}
  .menu-svc,.menu-areas{width:auto}
  .acc-tg:checked ~ .menu{display:block}
  .menu-cols{display:block;padding:0 0 10px}
  .menu-group{border-left:0;padding:0}
  .menu-group .mg-t{margin:0;padding:15px 10px 5px 16px}
  .menu-group a{padding:12px 10px 12px 16px;font-size:15.2px;border-left:3px solid var(--h-line);border-radius:0}
  .menu-group a small{display:none}
  .menu-group .all{border-top:0;margin-top:2px;padding-top:12px;border-left-color:var(--h-red)}
  .menu-list{padding:0 0 12px;columns:1 !important}
  .menu-list a{padding:12px 10px 12px 16px;font-size:15.2px;border-left:3px solid var(--h-line);border-radius:0}
  .menu-list a small{display:none}
  .menu-list .all{border-top:0;padding-top:12px;margin-top:2px;border-left-color:var(--h-red)}
  .menu-aside{display:none}
  .hdr-actions{margin-left:auto;padding:0}
  .hdr-phone span{display:none}
  .hdr-phone{padding:11px;border:2px solid var(--h-line);border-radius:9px}
  .hdr-burger{
    display:inline-flex;align-items:center;justify-content:center;width:48px;height:48px;
    border:2px solid var(--h-char);border-radius:9px;cursor:pointer;flex:0 0 auto;background:transparent;
  }
  .hdr-burger svg{width:22px;height:22px;stroke:var(--h-char);fill:none;stroke-width:2.4;stroke-linecap:round}
  .hdr-burger .ico-x{display:none}
  .nav-tg:checked ~ .hdr-bar .hdr-burger{background:var(--h-char)}
  .nav-tg:checked ~ .hdr-bar .hdr-burger svg{stroke:#fff}
  .nav-tg:checked ~ .hdr-bar .hdr-burger .ico-x{display:block}
  .nav-tg:checked ~ .hdr-bar .hdr-burger .ico-bars{display:none}
  .nav-tg:focus-visible ~ .hdr-bar .hdr-burger{outline:3px solid var(--h-char);outline-offset:2px}
}
@media (max-width:820px){
  /* the side tab and the back to top button would sit over content on a narrow
     screen, and the bottom bar takes over there anyway */
  .qq-dock{display:none}
  .site-header a.to-top{display:none}
  .mbar .quote:focus-visible{outline-color:#fff}
  .mbar{
    display:grid;grid-template-columns:1fr 1fr;gap:10px;position:fixed;left:0;right:0;bottom:0;z-index:880;
    background:rgba(20,24,28,.97);border-top:3px solid var(--h-red);
    padding:10px 14px calc(10px + env(safe-area-inset-bottom));
  }
  .mbar a,.mbar label{
    display:flex;align-items:center;justify-content:center;gap:9px;min-height:50px;border-radius:9px;
    font-weight:800;font-size:15px;cursor:pointer;border:2px solid transparent;
  }
  .mbar svg{width:16px;height:16px;flex:0 0 auto}
  .site-header .mbar .call{background:transparent;color:#fff;border-color:#39424D}
  .mbar .call svg{fill:var(--h-red)}
  .mbar .call:hover{border-color:var(--h-red)}
  .site-header .mbar .quote{background:var(--h-red-ink);color:#fff;border-color:var(--h-red-ink)}
  .mbar .quote svg{fill:#fff}
  .mbar .quote:hover{background:var(--h-red);border-color:var(--h-red)}
  .qq-panel{width:100%;border-left:0;border-top:3px solid var(--h-red)}
}
@media (max-width:680px){
  .hdr-bar{gap:10px;padding:0 16px}
  .hdr-phone{display:none}
  .hdr-cta{padding:12px 16px;font-size:13.8px}
  .hdr-logo .lg-compact{height:38px}
  .hdr-nav{inset:70px 0 auto 0}
}
@media (max-width:400px){
  .hdr-bar{gap:8px;padding:0 12px;min-height:64px}
  .hdr-logo .lg-compact{height:36px}
  .hdr-cta{padding:11px 13px;font-size:13px}
  .hdr-burger{width:44px;height:44px}
  .hdr-nav{inset:64px 0 auto 0;max-height:calc(100dvh - 64px)}
  .qq-head,.qq-body{padding-left:20px;padding-right:20px}
}
@media (prefers-reduced-motion:reduce){
  .hdr-nav,.menu,.qq-panel,.qq-scrim,.qq-tab,.nav-top .chev,.acc-btn .chev{transition:none !important}
}
@media print{.site-header,.qq-dock,.qq-panel,.qq-scrim,.mbar{display:none !important}}



/* ==========================================================================
   All Walls & Ceilings Plastering. Page design system, V2.
   Plaster surfaces, charcoal contrast, verified red accent.
   ========================================================================== */
*,*::before,*::after{box-sizing:border-box}
:root{
  /* Approved All Walls & Ceilings Plastering brand colours, from the supplied logo package */
  --plaster:#F7F6F2;      /* Warm White */
  --plaster-2:#EFEDE6;
  --plaster-3:#E5E2D8;
  --char:#202124;         /* Charcoal */
  --char-2:#2B2D31;
  --line:#DFDCD2;
  --line-dk:#3A3D42;
  --text:#26282C;
  --muted:#5E6167;
  --muted-dk:#AFB3B9;
  --red:#E1252D;          /* Trade Red */
  --red-ink:#B31D23;      /* darker state, for small red text and hovers */
  --red-tint:#FBEBEC;
  --wrap:1280px;
  --font:"Inter",system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --tex:url("../assets/motif/plaster-texture.svg");
}
html{-webkit-text-size-adjust:100%}
body{
  margin:0;background:var(--plaster);color:var(--text);
  font-family:var(--font);font-size:17px;line-height:1.62;-webkit-font-smoothing:antialiased;
}
img{max-width:100%;height:auto;display:block}
a{color:var(--red-ink);text-decoration:underline;text-underline-offset:3px;text-decoration-thickness:1.5px}
a:hover{color:var(--char)}
h1,h2,h3,h4{font-weight:800;line-height:1.09;letter-spacing:-.028em;color:var(--char);margin:0 0 .5em}
h1{font-size:clamp(2.3rem,1.3rem + 3.5vw,3.95rem);font-weight:900;letter-spacing:-.04em}
h2{font-size:clamp(1.72rem,1.14rem + 2.25vw,2.78rem);font-weight:900;letter-spacing:-.034em}
h3{font-size:clamp(1.1rem,1.02rem + .34vw,1.26rem);letter-spacing:-.012em}
p{margin:0 0 1.05em}
ul{margin:0 0 1.05em;padding-left:1.15em}
li{margin-bottom:.4em}
:focus-visible{outline:3px solid var(--char);outline-offset:2px;border-radius:4px}
.sec--ink :focus-visible,.final :focus-visible,.site-footer :focus-visible{outline-color:var(--red)}

.pg-top{position:absolute;top:0;left:0;width:1px;height:1px;overflow:hidden;pointer-events:none}
.skip-link{
  position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;
  left:0;top:0;z-index:1000;background:var(--red-ink);color:#fff;font-weight:800;padding:14px 20px;
  border-radius:0 0 8px 0;font-family:var(--font);text-decoration:none;
}
.skip-link:focus{width:auto;height:auto;clip-path:none;overflow:visible}

.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.sec{padding:clamp(56px,7vw,104px) 0;position:relative}
.sec--plaster{background:var(--plaster-2)}
.sec--plaster::before{content:"";position:absolute;inset:0;background:var(--tex) repeat;opacity:.5;mix-blend-mode:multiply;pointer-events:none}
.sec--plaster > .wrap{position:relative;z-index:1}
.sec--ink{background:var(--char);color:#C9D0D8}
.sec--ink h2,.sec--ink h3{color:#fff}

/* ---------- motif helpers ---------- */
.mot{display:block;color:var(--red)}
.mot-svg{display:block;width:100%;height:100%;overflow:visible}
.eyebrow{
  position:relative;display:inline-flex;align-items:center;
  padding:10px 24px;margin:0 0 20px;color:#fff;
  font-size:12.4px;font-weight:800;letter-spacing:.155em;text-transform:uppercase;line-height:1;
}
.eyebrow > svg{position:absolute;inset:0;width:100%;height:100%;color:var(--red-ink);z-index:1}
.eyebrow > span{position:relative;z-index:2}
/* the motif is reserved for four positions; everywhere else the label is plain type */
.eyebrow--plain{padding:0 0 0 22px;color:var(--red-ink);margin-bottom:16px}
.eyebrow--plain::before{content:"";position:absolute;left:0;top:50%;transform:translateY(-50%);width:14px;height:3px;background:var(--red)}
.sec--ink .eyebrow--plain,.final .eyebrow--plain{color:var(--red)}
.sec--ink .eyebrow > svg,.final .eyebrow > svg{color:var(--red)}
.sec--ink .eyebrow > span,.final .eyebrow > span{color:#fff}

.slab{position:relative;display:inline-block;white-space:nowrap;padding:0 .1em}
/* the motif has to clear descenders: the p in "plasterers" dropped below it */
.slab > svg{position:absolute;left:-1%;top:-4%;width:102%;height:110%;color:var(--red);z-index:1}
.slab > span{position:relative;z-index:2;color:#fff}

.h2-ul{display:block;width:clamp(150px,22vw,260px);height:17px;color:var(--red-ink);margin:-2px 0 24px}
.sec--ink .h2-ul,.final .h2-ul{color:var(--red)}

.edge{position:absolute;left:0;right:0;height:clamp(28px,3.4vw,52px);line-height:0;pointer-events:none;z-index:2}
.edge svg{width:100%;height:100%;display:block}
.edge--t{top:0;transform:translateY(-99%)}
.edge--b{bottom:0;transform:translateY(99%)}
.edge--ink{color:var(--char)}
.edge--plaster{color:var(--plaster-2)}

.lede{font-size:clamp(1.05rem,.98rem + .34vw,1.2rem);color:var(--muted);max-width:66ch}
.sec--ink .lede,.final .lede{color:var(--muted-dk)}
.head{max-width:820px;margin-bottom:clamp(34px,4vw,52px)}
@media (min-width:1000px){
  /* editorial split so the heading does not leave the right half of the page empty */
  .head:not(.head--center):not(.head--solo){
    max-width:none;display:grid;grid-template-columns:1.06fr .94fr;
    column-gap:clamp(44px,5vw,88px);align-items:end;
  }
  .head:not(.head--center):not(.head--solo) > .eyebrow{grid-column:1;grid-row:1;justify-self:start}
  .head:not(.head--center):not(.head--solo) > h2{grid-column:1;grid-row:2;margin-bottom:0}
  .head:not(.head--center):not(.head--solo) > .h2-ul{grid-column:1;grid-row:3}
  .head:not(.head--center):not(.head--solo) > .lede{grid-column:2;grid-row:2 / span 2;align-self:end;margin:0 0 10px}
}
.head--solo{max-width:820px}
.head--center{text-align:center;margin-left:auto;margin-right:auto;max-width:760px}
.head--center .h2-ul{margin-left:auto;margin-right:auto}

/* ---------- buttons ---------- */
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:9px;
  font-family:var(--font);font-weight:800;font-size:15.6px;letter-spacing:.008em;
  padding:16px 28px;border-radius:9px;border:2px solid transparent;cursor:pointer;
  text-decoration:none;min-height:52px;transition:background .15s ease,color .15s ease,border-color .15s ease;
}
.btn svg{width:16px;height:16px;flex:0 0 auto}
.btn--red{background:var(--red-ink);color:#fff;border-color:var(--red-ink)}
.btn--red svg{fill:#fff}
.btn--red:hover,.btn--red:focus-visible{background:var(--red);border-color:var(--red);color:#fff}
.btn--line{background:transparent;color:var(--char);border-color:#BFB6A6}
.btn--line svg{fill:var(--red-ink)}
.btn--line:hover,.btn--line:focus-visible{background:var(--char);border-color:var(--char);color:#fff}
.btn--line:hover svg,.btn--line:focus-visible svg{fill:var(--red)}
.btn--line-lt{background:transparent;color:#fff;border-color:#3D4650}
.btn--line-lt svg{fill:var(--red)}
.btn--line-lt:hover,.btn--line-lt:focus-visible{background:var(--char-2);border-color:var(--red);color:#fff}
.btn-row{display:flex;flex-wrap:wrap;gap:13px;margin:30px 0 0}

/* ==================== HERO ==================== */
.hero{position:relative;padding:clamp(40px,4.6vw,70px) 0 clamp(54px,6vw,92px);overflow:hidden}
.hero::before{content:"";position:absolute;inset:0;background:var(--tex) repeat;opacity:.55;mix-blend-mode:multiply;pointer-events:none}
.hero::after{
  content:"";position:absolute;right:-8%;top:-18%;width:46%;height:70%;
  background:radial-gradient(closest-side,rgba(225,37,45,.07),transparent 70%);pointer-events:none;
}
.hero-grid{position:relative;z-index:1;display:grid;grid-template-columns:1.04fr .96fr;gap:clamp(30px,4.5vw,72px);align-items:center}
.hero h1{margin-bottom:22px}
.hero-sub{
  font-size:clamp(1.12rem,1rem + .55vw,1.42rem);font-weight:600;color:var(--char);
  max-width:24ch;margin-bottom:16px;line-height:1.35;
}
.hero-body{color:var(--muted);max-width:52ch}
.hero-trust{display:flex;flex-wrap:wrap;gap:0;margin:32px 0 0;padding:0;list-style:none;border-top:1px solid var(--line)}
.hero-trust li{
  flex:1 1 150px;padding:15px 18px 0 0;font-size:14.2px;font-weight:700;color:var(--char);line-height:1.4;
  position:relative;
}
.hero-trust li::before{content:"";position:absolute;left:0;top:-1px;width:32px;height:3px;background:var(--red)}
.hero-trust li span{display:block;font-weight:500;color:var(--muted);font-size:13.4px;margin-top:3px}

.hero-media{position:relative}
.hero-band{position:absolute;left:-26px;top:-22px;bottom:-22px;width:56px;color:var(--red);opacity:.92;z-index:1}
.hero-band svg{width:100%;height:100%;display:block}
.hero-shot{position:relative;z-index:2;overflow:hidden;
  -webkit-mask:linear-gradient(#000,#000) top/100% calc(100% - 26px) no-repeat, var(--edge-mask) bottom/100% 27px no-repeat;
  mask:linear-gradient(#000,#000) top/100% calc(100% - 26px) no-repeat, var(--edge-mask) bottom/100% 27px no-repeat;
}
.hero-shot img{width:100%;aspect-ratio:4/3;object-fit:cover;object-position:center 46%}
.hero-detail{
  position:absolute;right:-14px;bottom:-30px;z-index:3;width:min(206px,40%);
  border:7px solid var(--plaster);box-shadow:0 22px 44px -18px rgba(20,24,28,.45);
}
.hero-detail img{width:100%;aspect-ratio:4/5;object-fit:cover;object-position:34% center;display:block}
.hero-detail-cap{
  position:absolute;left:-7px;bottom:-7px;background:var(--red-ink);color:#fff;
  font-size:11.4px;font-weight:800;letter-spacing:.11em;text-transform:uppercase;padding:7px 12px;
}
.hero-cap{
  position:absolute;left:0;bottom:-30px;z-index:3;background:var(--char);color:#fff;
  font-size:12.4px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:9px 15px;
  border-left:4px solid var(--red);
}

/* ==================== SERVICE FAMILIES ==================== */
.fam-tag{
  margin:0 0 10px;font-size:11.6px;font-weight:800;letter-spacing:.155em;text-transform:uppercase;
  color:var(--muted);display:flex;align-items:center;gap:11px;
}
.fam-tag::after{content:"";flex:1;height:1px;background:var(--line)}
.fam-tag--lead{color:var(--red-ink)}
.fam-tag--lead::after{background:var(--red);opacity:.45}
.fam-lede{margin:0 0 22px;font-size:16.4px;line-height:1.62;color:var(--muted)}

.fam-head{max-width:760px;margin-bottom:26px}

.prep{
  margin-top:clamp(44px,5vw,70px);display:grid;grid-template-columns:1fr 1fr auto;gap:26px;align-items:center;
  background:var(--plaster-2);border:1px solid var(--line);border-left:4px solid var(--red);
  border-radius:0 12px 12px 0;padding:24px 26px;
}
.prep-t p:last-child{margin:0;font-size:14.6px;line-height:1.55;color:var(--muted)}
.prep-t .fam-tag{margin-bottom:6px}
.prep-link{display:flex;align-items:center;gap:12px;text-decoration:none}
.prep-link b{font-size:17px;font-weight:800;color:var(--text);display:block;white-space:nowrap}
/* the label names the action in full, so it is allowed to wrap once the row narrows */
@media (max-width:760px){.prep-link b{white-space:normal}.prep-link{align-items:flex-start}}
.prep-link span{font-size:13.6px;color:var(--muted);display:block}
.prep-link svg{width:17px;height:17px;fill:var(--red-ink);flex:0 0 auto;transition:transform .16s ease}
.prep-link:hover b{color:var(--red-ink)}
.prep-link:hover svg{transform:translateX(5px)}
.prep-all{
  display:inline-flex;align-items:center;gap:9px;white-space:nowrap;font-weight:800;font-size:14.6px;
  color:#fff;background:var(--red-ink);border:2px solid var(--red-ink);border-radius:9px;padding:13px 19px;text-decoration:none;
}
.prep-all svg{width:15px;height:15px;fill:#fff}
.prep-all:hover,.prep-all:focus-visible{background:var(--red);border-color:var(--red)}
@media (max-width:1040px){
  .prep{grid-template-columns:1fr;gap:18px;border-radius:0 10px 10px 0}
}

/* ==================== TOPIC DEPTH ==================== */
.depth{display:grid;grid-template-columns:1.18fr .82fr;gap:clamp(36px,4.4vw,72px);align-items:start}
.dp-copy h2{margin:0 0 14px}
.dp-copy .lede{margin:0 0 30px}
.dp-list{list-style:none;margin:0;padding:0}
.dp-list li{padding:22px 0;border-top:1px solid var(--line)}
.dp-list li:last-child{border-bottom:1px solid var(--line)}
.dp-list h3{margin:0 0 7px;font-size:clamp(1.06rem,1rem + .3vw,1.24rem);letter-spacing:-.014em}
.dp-list p{margin:0 0 11px;font-size:15.4px;line-height:1.62;color:var(--muted)}
.dp-list a{display:inline-flex;align-items:center;gap:8px;font-weight:800;font-size:14.2px;color:var(--red-ink);text-decoration:none}
.dp-list a svg{width:15px;height:15px;fill:var(--red-ink);transition:transform .16s ease}
.dp-list a:hover{text-decoration:underline}
.dp-list a:hover svg{transform:translateX(4px)}
.dp-media{position:sticky;top:104px;display:grid;gap:18px}
.dp-shot{position:relative;border:6px solid #fff;box-shadow:0 20px 40px -22px rgba(20,24,28,.44)}
.dp-shot img{display:block;width:100%;aspect-ratio:4/3;object-fit:cover}
.dp-cap{
  display:block;background:var(--char);color:#fff;font-size:11.8px;font-weight:700;
  letter-spacing:.055em;text-transform:uppercase;padding:9px 13px;border-left:4px solid var(--red);
}

/* ==================== SEQUENCE ==================== */
.seq{list-style:none;margin:0;padding:0;display:grid;
  grid-template-columns:repeat(var(--seq-cols,5),1fr);gap:0}
/* The variant names the number of steps. Desktop column counts are chosen so that no row
   is left holding a single stranded step: six steps run three across and twice down, never
   five across with one underneath. */
.seq--1{--seq-cols:1}.seq--2{--seq-cols:2}.seq--3{--seq-cols:3}.seq--4{--seq-cols:4}
.seq--5{--seq-cols:5}.seq--6{--seq-cols:3}.seq--7{--seq-cols:4}.seq--8{--seq-cols:4}
.seq--9{--seq-cols:3}.seq--10{--seq-cols:5}.seq--11{--seq-cols:4}.seq--12{--seq-cols:4}
/* a second row needs its own breathing room above the step number */
.seq--6 .seq-step,.seq--7 .seq-step,.seq--8 .seq-step,.seq--9 .seq-step,
.seq--10 .seq-step,.seq--11 .seq-step,.seq--12 .seq-step{padding-top:26px}
.seq-step{position:relative;padding:30px 20px 24px 0}
.seq-step::before{content:"";position:absolute;left:0;right:0;top:0;height:4px}
.seq-step--rep::before{background:var(--red)}
.seq-step--fin::before{background:var(--char)}
.seq-step .n{
  display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;border-radius:50%;
  font-size:13px;font-weight:800;margin-bottom:13px;
}
.seq-step--rep .n{background:var(--red-ink);color:#fff}
.seq-step--fin .n{background:var(--char);color:#fff}
.seq-step h3{margin:0 0 8px;font-size:1.06rem;letter-spacing:-.014em}
.seq-step p{margin:0;font-size:14.6px;line-height:1.6;color:var(--muted)}
.seq-key{display:flex;flex-wrap:wrap;gap:10px 22px;margin:26px 0 0;font-size:13.6px;font-weight:700}
.seq-k{display:inline-flex;align-items:center;gap:9px;color:var(--muted)}
.seq-k::before{content:"";width:16px;height:4px;border-radius:2px;flex:0 0 auto}
.seq-k--rep::before{background:var(--red)}
.seq-k--fin::before{background:var(--char)}
.seq-k--note{color:var(--text)}
.seq-k--note::before{display:none}
@media (max-width:1040px){
  .depth{grid-template-columns:1fr}
  .dp-media{position:static;grid-template-columns:1fr 1fr}
  /* Tablet takes two columns from four steps up. Three steps stay three across, because
     two columns would leave the third step alone on a row of its own. */
  .seq{gap:0 22px}
  .seq--4,.seq--5,.seq--6,.seq--7,.seq--8,.seq--9,.seq--10,.seq--11,.seq--12{--seq-cols:2}
  .seq--3{--seq-cols:3}
  .seq--2{--seq-cols:2}
  /* An odd number of steps across two columns would leave the last one alone in half a
     row. It takes the full width instead, so the final step reads as deliberate. */
  .seq--5 .seq-step:last-child,.seq--7 .seq-step:last-child,
  .seq--9 .seq-step:last-child,.seq--11 .seq-step:last-child{grid-column:1 / -1}
  .seq-step{padding-right:0}
}
@media (max-width:620px){
  .dp-media{grid-template-columns:1fr}
  .seq,.seq--2,.seq--3,.seq--4,.seq--5,.seq--6,.seq--7,.seq--8,.seq--9,
  .seq--10,.seq--11,.seq--12{--seq-cols:1}
}

/* ==================== PROOF STRIP ==================== */
.proof{background:var(--char);color:#C9D0D8;padding:clamp(40px,4.4vw,58px) 0;position:relative}
.proof-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(18px,2.6vw,38px)}
.proof-item{padding-left:20px;border-left:3px solid var(--red)}
.proof-item .pf-t{font-size:1.02rem;font-weight:800;letter-spacing:-.005em;margin:0 0 5px;color:#fff}
.proof-item p{margin:0;font-size:14.2px;color:var(--muted-dk);line-height:1.55}

/* ==================== SYMPTOMS ==================== */
.symp{display:grid;grid-template-columns:repeat(3,1fr);gap:0 clamp(24px,3vw,46px)}
.symp a{
  display:block;text-decoration:none;color:inherit;padding:26px 0 24px;border-top:1px solid var(--line);
  position:relative;transition:padding-left .16s ease;
}
.symp a::before{content:"";position:absolute;left:0;top:-1px;width:0;height:3px;background:var(--red);transition:width .2s ease}
.symp a:hover::before,.symp a:focus-visible::before{width:100%}
.symp a:hover,.symp a:focus-visible{padding-left:10px}
.symp .n{
  display:block;font-size:12.6px;font-weight:800;letter-spacing:.16em;color:var(--red-ink);margin-bottom:11px;
}
.symp h3{margin:0 0 9px;font-size:1.22rem}
.symp p{margin:0 0 14px;font-size:15px;color:var(--muted);line-height:1.58}
.symp .go{font-size:13.8px;font-weight:800;color:var(--red-ink);display:inline-flex;align-items:center;gap:8px;min-height:24px}
.symp .go svg{width:13px;height:13px;fill:currentColor;transition:transform .16s ease}
.symp a:hover .go svg{transform:translateX(4px)}

/* ==================== SERVICES INDEX ==================== */
.svc-layout{display:grid;grid-template-columns:.92fr 1.08fr;gap:clamp(30px,4vw,64px);align-items:start}
.svc-side{position:sticky;top:110px}
.svc-shot{position:relative;margin-top:28px}
.svc-shot img{width:100%;aspect-ratio:4/5;object-fit:cover;object-position:center 40%}
.svc-shot{-webkit-mask:linear-gradient(#000,#000) top/100% calc(100% - 22px) no-repeat, var(--edge-mask) bottom/100% 23px no-repeat;
  mask:linear-gradient(#000,#000) top/100% calc(100% - 22px) no-repeat, var(--edge-mask) bottom/100% 23px no-repeat}
.svc-index{margin:0;padding:0;list-style:none;border-top:2px solid var(--char)}
.svc-index li{border-bottom:1px solid var(--line)}
.svc-index a{
  display:grid;grid-template-columns:auto 1fr auto;gap:0 20px;align-items:baseline;
  padding:22px 4px 22px 0;text-decoration:none;color:inherit;position:relative;
  transition:padding-left .18s ease,background .18s ease;
}
.svc-index a::before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--red);
  transform:scaleY(0);transform-origin:top;transition:transform .2s ease}
.svc-index a:hover,.svc-index a:focus-visible{padding-left:18px;background:var(--plaster-2)}
.svc-index a:hover::before,.svc-index a:focus-visible::before{transform:scaleY(1)}
.svc-index .num{font-size:13px;font-weight:800;color:var(--red-ink);letter-spacing:.06em;align-self:center;min-width:26px}
.svc-index .nm{display:block}
.svc-index .nm b{display:block;font-size:clamp(1.24rem,1.08rem + .58vw,1.6rem);font-weight:800;
  letter-spacing:-.022em;color:var(--char);line-height:1.18;margin-bottom:4px}
.svc-index .nm span{display:block;font-size:14.6px;color:var(--muted);line-height:1.5}
.svc-index .arw{align-self:center;width:34px;height:34px;border-radius:50%;border:2px solid var(--line);
  display:flex;align-items:center;justify-content:center;flex:0 0 auto;transition:border-color .18s,background .18s}
.svc-index .arw svg{width:12px;height:12px;fill:var(--red-ink)}
.svc-index a:hover .arw,.svc-index a:focus-visible .arw{border-color:var(--red-ink);background:var(--red-ink)}
.svc-index a:hover .arw svg,.svc-index a:focus-visible .arw svg{fill:#fff}

/* ==================== TRIAGE ==================== */
.triage{display:grid;grid-template-columns:1fr 1fr;gap:clamp(22px,3vw,44px)}
.triage-col h3{display:flex;align-items:center;gap:11px;font-size:1.2rem;margin-bottom:18px;padding-bottom:14px;
  border-bottom:2px solid currentColor}
.triage-col:first-child h3{color:#fff;border-bottom-color:#4E9A73}
.triage-col:last-child h3{color:#fff;border-bottom-color:var(--red)}
.triage-col h3 svg{width:20px;height:20px;flex:0 0 auto}
.triage-col:first-child h3 svg{fill:#4E9A73}
.triage-col:last-child h3 svg{fill:var(--red)}
.triage-col ul{margin:0;padding:0;list-style:none}
.triage-col li{font-size:15.2px;padding-left:26px;position:relative;margin-bottom:13px;line-height:1.52;color:#C9D0D8}
.triage-col li::before{position:absolute;left:0;top:.5em;width:10px;height:2px;content:"";background:currentColor;opacity:.55}
.triage-col:first-child li::before{background:#4E9A73;opacity:1}
.triage-col:last-child li::before{background:var(--red);opacity:1}

/* ==================== SPLIT ==================== */
.split{display:grid;grid-template-columns:1.02fr .98fr;gap:clamp(28px,4vw,62px);align-items:stretch}
.split > div:not(.split-media){display:flex;flex-direction:column;justify-content:center}
.split > div:not(.split-media) > *:first-child{margin-top:0}
.split-media{align-self:center}
.split-media{position:relative}
.split-media img{width:100%;aspect-ratio:4/5;object-fit:cover;object-position:center 44%}
.split-media{-webkit-mask:linear-gradient(#000,#000) bottom/100% calc(100% - 22px) no-repeat, var(--edge-mask-t) top/100% 23px no-repeat;
  mask:linear-gradient(#000,#000) bottom/100% calc(100% - 22px) no-repeat, var(--edge-mask-t) top/100% 23px no-repeat}
.steps{margin:24px 0 0;padding:0;list-style:none;counter-reset:s}
.steps li{counter-increment:s;padding-left:50px;position:relative;margin-bottom:18px;font-size:15.4px;line-height:1.56}
.steps li:last-child{margin-bottom:0}
.steps li::before{
  content:counter(s);position:absolute;left:0;top:-2px;width:34px;height:34px;
  background:var(--red-ink);color:#fff;font-weight:800;font-size:14px;
  display:flex;align-items:center;justify-content:center;border-radius:9px;
}
.steps b{color:var(--char);font-weight:800}

/* ==================== PROCESS ==================== */
.process{display:grid;grid-template-columns:repeat(4,1fr);gap:0}
.process-step{padding:0 26px 0 0;position:relative}
.process-step + .process-step{padding-left:26px;border-left:1px solid var(--line)}
.process-step .n{
  display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;border-radius:10px;
  background:var(--char);color:#fff;font-weight:800;font-size:14px;margin-bottom:16px;
}
.process-step:first-child .n{background:var(--red-ink)}
.process-step h3{margin:0 0 8px;font-size:1.08rem}
.process-step p{margin:0;font-size:14.8px;color:var(--muted);line-height:1.56}

/* ==================== WORK ==================== */
.work-lead{display:grid;grid-template-columns:1fr 1fr;gap:clamp(20px,2.6vw,34px);align-items:end}
.work-fig{margin:0;position:relative}
.work-fig img{width:100%;aspect-ratio:3/4;object-fit:cover;object-position:center 44%}
.work-fig figcaption{padding:16px 0 0;font-size:14.4px;color:var(--muted);line-height:1.5}
.work-fig figcaption b{display:block;color:var(--char);font-weight:800;font-size:14.8px;margin-bottom:3px}
.work-tag{
  position:absolute;top:14px;left:0;background:var(--char);color:#fff;padding:7px 14px;
  font-size:11.6px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;border-left:4px solid var(--red);
}
.work-note{margin-top:26px;padding-left:20px;border-left:3px solid var(--red);font-size:14.8px;color:var(--muted);max-width:74ch}
.work-note strong{color:var(--char)}

/* ==================== AREAS ==================== */
.areas{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(28px,4vw,62px);align-items:start}
.area-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:0 clamp(18px,2.4vw,34px);margin:0;padding:0;list-style:none}
.area-grid li{border-top:1px solid var(--line)}
.area-grid a{
  display:flex;align-items:center;justify-content:space-between;gap:12px;padding:15px 2px;
  text-decoration:none;color:var(--char);font-weight:700;font-size:15.4px;position:relative;
  transition:padding-left .16s ease;
}
.area-grid a::before{content:"";position:absolute;left:0;top:-1px;width:0;height:2px;background:var(--red);transition:width .2s}
.area-grid a:hover,.area-grid a:focus-visible{padding-left:10px;color:var(--red-ink)}
.area-grid a:hover::before,.area-grid a:focus-visible::before{width:100%}
.area-grid svg{width:12px;height:12px;fill:var(--red-ink);flex:0 0 auto}
.area-note{margin-top:24px;padding:20px 22px;background:var(--plaster-2);border-left:4px solid var(--red)}
.area-note p{margin:0;font-size:14.8px;color:var(--muted);line-height:1.6}
.area-note strong{color:var(--char)}

/* ==================== PRICING FACTORS ==================== */
.factors{columns:2;column-gap:clamp(30px,4vw,62px)}
.factor{break-inside:avoid;padding:0 0 22px;margin-bottom:22px;border-bottom:1px solid var(--line)}
.factor h3{margin:0 0 6px;font-size:1.04rem;display:flex;align-items:baseline;gap:10px}
.factor h3::before{content:"";width:14px;height:3px;background:var(--red);flex:0 0 auto;position:relative;top:-4px}
.factor p{margin:0;font-size:14.8px;color:var(--muted);line-height:1.56}

/* ==================== FAQ ==================== */
.faq-layout{display:grid;grid-template-columns:.78fr 1.22fr;gap:clamp(30px,4vw,64px);align-items:start}
.faq-side{position:sticky;top:120px}
.faq-side .btn-row{margin-top:26px}
.faq{max-width:none}
.faq details{border-bottom:1px solid var(--line)}
.faq details:first-of-type{border-top:2px solid var(--char)}
.faq summary{
  list-style:none;cursor:pointer;padding:23px 46px 23px 0;position:relative;
  font-weight:800;font-size:clamp(1rem,.96rem + .26vw,1.14rem);color:var(--char);line-height:1.4;letter-spacing:-.01em;
}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{
  content:"";position:absolute;right:6px;top:50%;width:14px;height:2.6px;background:var(--red-ink);
  transform:translateY(-50%);
}
.faq summary::before{
  content:"";position:absolute;right:11.7px;top:50%;width:2.6px;height:14px;background:var(--red-ink);
  transform:translateY(-50%);transition:transform .2s ease;
}
.faq details[open] summary::before{transform:translateY(-50%) scaleY(0)}
.faq summary:hover{color:var(--red-ink)}
.faq .a{padding:0 46px 24px 0;font-size:15.6px;color:var(--muted);line-height:1.68}
.faq .a p:last-child{margin-bottom:0}

/* ==================== FINAL ==================== */
.final{background:var(--char);color:#C9D0D8;padding:clamp(60px,6.5vw,100px) 0;position:relative;overflow:hidden}
.final::after{content:"";position:absolute;left:50%;top:-30%;width:70%;height:160%;transform:translateX(-50%);
  background:radial-gradient(closest-side,rgba(225,37,45,.13),transparent 72%);pointer-events:none}
.final .wrap{position:relative;z-index:1;text-align:center}
.final h2{color:#fff}
.final .lede{margin-left:auto;margin-right:auto}
.final .btn-row{justify-content:center}

/* ==================== FOOTER ==================== */
.site-footer{background:#0B0E12;color:#98A2AE;font-size:14.6px;padding:clamp(50px,5vw,72px) 0 0}
.site-footer h3{color:#fff;font-size:12.6px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;margin:0 0 16px;
  padding-bottom:10px;border-bottom:2px solid var(--red)}
.ft-grid{display:grid;grid-template-columns:1.15fr .88fr .88fr .88fr .88fr .86fr .7fr;gap:clamp(13px,1.5vw,26px)}
.ft-col-list h3{font-size:11px}
.ft-logo img{height:46px;width:auto;margin-bottom:18px}
.ft-about p{margin:0 0 18px;line-height:1.65;max-width:38ch}
.ft-contact a{display:inline-flex;align-items:center;gap:9px;color:#fff;font-weight:800;text-decoration:none;font-size:17px}
.ft-contact a:hover{color:var(--red)}
.ft-contact svg{width:16px;height:16px;fill:var(--red)}
.site-footer a.ft-cta{display:inline-flex;align-items:center;justify-content:center;background:var(--red-ink);color:#fff;
  font-weight:800;font-size:14.4px;padding:13px 20px;border-radius:9px;text-decoration:none;margin-top:18px;
  border:2px solid var(--red-ink)}
.ft-desc{
  margin:12px 0 14px;font-size:8.6px;font-weight:800;letter-spacing:.092em;text-transform:uppercase;color:#AFB3B9;
}
.ft-desc span{color:#F2545B;margin:0 3px}
.site-footer a.ft-cta:hover,.site-footer a.ft-cta:focus-visible{background:var(--red);border-color:var(--red);color:#fff}
.site-footer ul{list-style:none;margin:0;padding:0}
.site-footer li{margin-bottom:4px}
.site-footer li a{display:inline-block;padding:5px 0;min-height:26px}
.site-footer a{color:#98A2AE;text-decoration:none}
.site-footer a:hover,.site-footer a:focus-visible{color:var(--red);text-decoration:underline}
.ft-bottom{margin-top:clamp(34px,4vw,52px);border-top:1px solid #1E242B;padding:22px 0 26px;
  display:flex;flex-wrap:wrap;gap:14px 26px;align-items:center;justify-content:space-between;font-size:13.4px}
.ft-legal{display:flex;flex-wrap:wrap;gap:8px 20px;margin:0;padding:0;list-style:none}
.ft-legal li{margin:0}
.ft-credit{margin:0;display:inline-flex;align-items:center;gap:8px}
.ft-credit img{width:20px;height:20px;border-radius:6px;flex:0 0 auto}
.site-footer .ft-credit a{color:#B9C2CE;font-weight:700}
.site-footer .ft-credit a:hover,.site-footer .ft-credit a:focus-visible{color:var(--red)}

/* ==========================================================================
   Responsive
   ========================================================================== */
@media (max-width:1040px){
  .hero-grid{grid-template-columns:1fr;gap:38px}
  .hero-media{max-width:560px}
  .hero-band{left:-18px;width:44px}
  .proof-grid{grid-template-columns:repeat(2,1fr);gap:26px}
  .symp{grid-template-columns:repeat(2,1fr)}
  .svc-layout,.faq-layout{grid-template-columns:1fr;gap:34px}
  .svc-side,.faq-side{position:static}
  .svc-shot{max-width:440px;margin-top:22px}
  .split{grid-template-columns:1fr;gap:32px}
  .split-media{order:-1;max-width:460px}
  .process{grid-template-columns:repeat(2,1fr);gap:30px 0}
  .process-step:nth-child(3){padding-left:0;border-left:0}
  .areas{grid-template-columns:1fr;gap:32px}
  .ft-grid{grid-template-columns:1fr 1fr 1fr;gap:30px}
}
@media (max-width:860px){
  .triage{grid-template-columns:1fr;gap:30px}
  .factors{columns:1}
  .work-lead{grid-template-columns:1fr;gap:28px}
}
@media (max-width:680px){
  body{font-size:16.5px;padding-bottom:78px}
  .sec{padding:48px 0}
  .symp{grid-template-columns:1fr}
  .proof-grid{grid-template-columns:1fr;gap:20px}
  .process{grid-template-columns:1fr;gap:26px}
  .process-step{padding:0;border-left:0 !important;padding-left:0 !important}
  .area-grid{grid-template-columns:1fr}
  .ft-grid{grid-template-columns:1fr;gap:30px}
  .btn{width:100%}
  .hero-detail{width:40%;right:-6px;bottom:-24px}
  .hero-cap{font-size:11.4px;padding:8px 12px}
  .svc-index a{grid-template-columns:auto 1fr;gap:0 14px}
  .svc-index .arw{display:none}
  .hero-trust li{flex:1 1 100%;padding-right:0}
}
@media (max-width:400px){
  .wrap{padding:0 16px}
  .hero-detail{width:34%;right:-8px;bottom:-22px}
}
@media (prefers-reduced-motion:reduce){*{transition-duration:.01ms !important;animation-duration:.01ms !important}}

/* ==================== V4 ADDITIONS ==================== */
.svc-stack > .fam-tag{margin:0 0 12px}
.svc-stack > .svc-index + .fam-tag{margin-top:clamp(34px,4vw,48px)}
.dp-copy .fam-tag{margin-bottom:12px}
.dp-copy h2{margin:0 0 14px}
.svc-groups{display:grid;grid-template-columns:repeat(4,1fr);gap:0 clamp(18px,2.2vw,34px);margin-top:clamp(44px,5vw,74px)}
.svc-groups .fam-tag{margin-bottom:6px}
.area-grid--one{grid-template-columns:1fr}
.area-more{margin:20px 0 0;font-size:14.4px;line-height:1.6;color:var(--muted)}
.areas .fam-tag{margin-bottom:6px}
.dp-note{background:var(--char);color:#AEB7C1;padding:22px 22px 24px;border-left:4px solid var(--red)}
.dp-note .dp-note-t{color:#fff;font-weight:800;font-size:1.02rem;letter-spacing:-.01em;margin:0 0 9px;line-height:1.3}
.dp-note p{margin:0 0 16px;font-size:14.2px;line-height:1.6}
.dp-note a.dp-note-tel{display:inline-flex;align-items:center;gap:9px;color:#fff;font-weight:800;font-size:15.4px;text-decoration:none}
.dp-note a.dp-note-tel svg{width:15px;height:15px;fill:var(--red);flex:0 0 auto}
.dp-note a.dp-note-tel:hover,.dp-note a.dp-note-tel:focus-visible{color:var(--red)}
@media (max-width:1040px){
  .dp-media{position:static;grid-template-columns:1fr;max-width:460px}
  .svc-groups{grid-template-columns:1fr 1fr;gap:30px clamp(20px,3vw,34px)}
}
@media (max-width:680px){
  .svc-groups{grid-template-columns:1fr;gap:26px 0}
}
@media print{.sec,.hero{padding:20px 0}}



/* ==========================================================================
   All Walls & Ceilings Plastering. Inner-page component extension.
   Built only from the approved tokens in the page design system above.
   No new hue, no new typeface, no new global shell.
   ========================================================================== */
:root{
  --red-deep:#8E171C;   /* derived from --red for text on light surfaces */
  --red-lift:#F4696F;   /* derived from --red for text on charcoal */
  --line-soft:#EAE7DE;
  --line-strong:#CFCBBE;
  --ink-body:#C9D0D8;
  --ink-muted:#9AA1AA;
  --ink-line:#3A3D42;
  --sp-sec:clamp(56px,7vw,104px);
}

/* ---------- breadcrumb ---------- */
.crumb{background:var(--plaster-2);border-bottom:1px solid var(--line)}
.crumb ol{display:flex;flex-wrap:wrap;align-items:center;gap:0 8px;margin:0;padding:13px 0;list-style:none;
  font-size:13.2px;font-weight:600;color:var(--muted)}
.crumb li{margin:0;display:flex;align-items:center;gap:8px}
.crumb li+li::before{content:"";width:5px;height:5px;background:var(--line-strong);transform:rotate(45deg);display:block}
.crumb a{color:var(--muted);text-decoration:none}
.crumb a:hover,.crumb a:focus-visible{color:var(--red-ink);text-decoration:underline}
.crumb [aria-current]{color:var(--char);font-weight:800}

/* ---------- inner hero ---------- */
.hero--inner{padding:clamp(40px,4.6vw,72px) 0 clamp(44px,5vw,78px);background:var(--plaster);position:relative}
.hero--inner .hero-grid{grid-template-columns:1.06fr .94fr;gap:clamp(30px,4vw,64px);align-items:center}
.hero--inner h1{font-size:clamp(2.05rem,1.2rem + 3vw,3.3rem)}
.hero--inner .hero-sub{margin-bottom:.85em}
.hero--wide .hero-grid{grid-template-columns:1fr;max-width:920px}
.hero-pills{list-style:none;margin:20px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.hero-pills li{margin:0;background:var(--plaster-3);border:1px solid var(--line-strong);border-radius:999px;
  padding:6px 14px;font-size:13.2px;font-weight:700;color:var(--char)}
@media (max-width:900px){.hero--inner .hero-grid{grid-template-columns:1fr}}

/* ---------- scope: what this covers / what it does not ---------- */
.scope{display:grid;grid-template-columns:1fr 1fr;gap:clamp(18px,2.4vw,34px)}
.scope-col{background:#fff;border:1px solid var(--line);border-top:4px solid var(--char);padding:clamp(20px,2.4vw,30px);color:var(--text)}
.scope-col h3{color:var(--char)}
.scope-col--out{border-top-color:var(--red)}
.scope-col h3{display:flex;align-items:center;gap:10px;margin-bottom:.7em}
.scope-col h3 svg{width:19px;height:19px;flex:0 0 auto;fill:var(--char)}
.scope-col--out h3 svg{fill:var(--red-ink)}
.scope-col ul{margin:0;padding-left:1.1em}
.scope-col li{margin-bottom:.5em}
.scope-note{margin:18px 0 0;font-size:14.6px;color:var(--muted)}
@media (max-width:820px){.scope{grid-template-columns:1fr}}

/* ---------- comparison / spec tables ---------- */
.tbl-wrap{overflow-x:auto;border:1px solid var(--line);background:#fff;margin:0 0 20px;max-width:100%;min-width:0}
table.tbl{border-collapse:collapse;width:100%;font-size:15.2px;min-width:640px}
table.tbl th{background:var(--char);color:#fff;text-align:left;padding:12px 15px;font-weight:800;font-size:11.8px;
  letter-spacing:.07em;text-transform:uppercase;vertical-align:bottom}
table.tbl td{padding:13px 15px;border-top:1px solid var(--line);vertical-align:top;line-height:1.55;color:var(--text)}
table.tbl tbody tr:nth-child(even){background:var(--plaster)}
table.tbl td:first-child{font-weight:700;color:var(--char)}

/* ---------- tile grid ---------- */
.tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(14px,1.8vw,24px)}
.tiles--2{grid-template-columns:repeat(2,1fr)}
.tiles--4{grid-template-columns:repeat(4,1fr)}
.tile{background:#fff;border:1px solid var(--line);border-left:4px solid var(--red);padding:clamp(18px,2vw,26px);color:var(--text)}
.tile h3{color:var(--char)}
.tile h3{margin-bottom:.45em}
.tile p:last-child{margin-bottom:0}
.tile .tile-k{display:block;font-size:11.6px;font-weight:800;letter-spacing:.11em;text-transform:uppercase;
  color:var(--red-ink);margin-bottom:9px}
.sec--ink .tile{background:var(--char-2);border-color:var(--ink-line);color:var(--ink-body)}
.sec--ink .tile .tile-k{color:var(--red-lift)}
@media (max-width:980px){.tiles,.tiles--4{grid-template-columns:repeat(2,1fr)}}
@media (max-width:640px){.tiles,.tiles--2,.tiles--4{grid-template-columns:1fr}}

/* ---------- callout ---------- */
.callout{background:#fff;border:1px solid var(--line);border-left:5px solid var(--red);
  padding:clamp(20px,2.3vw,28px);margin:0 0 22px;color:var(--text)}
.callout h2,.callout h3{color:var(--char)}
.callout h2,.callout h3{margin-bottom:.5em}
/* a callout that opens its own section carries an h2 for the outline,
   but it must stay the size the design calls for */
.callout h2{font-size:clamp(1.1rem,1.02rem + .34vw,1.26rem);font-weight:800;letter-spacing:-.012em}
.callout p:last-child{margin-bottom:0}
.callout--ink{background:var(--char);border-color:var(--ink-line);color:var(--ink-body)}
.callout--ink h2,.callout--ink h3{color:#fff}
.sec--ink .callout{background:var(--char-2);border-color:var(--ink-line);color:var(--ink-body)}

/* ---------- linked cards (services from a location, related services) ---------- */
.lcards{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(14px,1.8vw,22px)}
.lcard{background:#fff;border:1px solid var(--line);padding:clamp(18px,2vw,24px);display:flex;flex-direction:column;color:var(--text)}
.lcard h3{margin-bottom:.45em;font-size:1.06rem}
.lcard h3 a{color:var(--char);text-decoration:none}
.lcard h3 a:hover,.lcard h3 a:focus-visible{color:var(--red-ink);text-decoration:underline}
.lcard p{font-size:15.4px;color:var(--muted);margin-bottom:.8em}
.lcard .go{margin-top:auto;font-size:13.6px;font-weight:800;letter-spacing:.02em;color:var(--red-ink);
  text-decoration:none;display:inline-flex;align-items:center;gap:8px}
.lcard .go svg{width:13px;height:13px;fill:currentColor}
.lcard .go:hover,.lcard .go:focus-visible{text-decoration:underline}
/* four cards read as a block of two by two, never as three with one stranded below */
.lcards--4,.lcards--2{grid-template-columns:repeat(2,1fr)}
.lcard h3{min-height:2.4em;display:flex;align-items:flex-start}
@media (max-width:980px){.lcards,.lcards--4{grid-template-columns:repeat(2,1fr)}}
@media (max-width:620px){.lcards,.lcards--2,.lcards--4{grid-template-columns:1fr}
  .lcard h3{min-height:0}}

/* ---------- local facts strip ---------- */
.lfacts{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}
.lfacts div{background:#fff;padding:18px 20px;color:var(--text)}
.lfacts dt{font-size:11.4px;font-weight:800;letter-spacing:.11em;text-transform:uppercase;color:var(--red-ink);margin-bottom:6px}
.lfacts dd{margin:0;font-weight:700;color:var(--char);line-height:1.45}
@media (max-width:860px){.lfacts{grid-template-columns:repeat(2,1fr)}}
@media (max-width:480px){.lfacts{grid-template-columns:1fr}}

/* ---------- nearby links ---------- */
.nearby{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:9px}
.nearby li{margin:0}
.nearby a{display:inline-block;background:#fff;border:1px solid var(--line-strong);padding:9px 16px;
  font-size:14.4px;font-weight:700;color:var(--char);text-decoration:none;border-radius:2px}
.nearby a:hover,.nearby a:focus-visible{border-color:var(--red);color:var(--red-ink)}
.sec--plaster .nearby a{background:#fff}

/* ---------- index list (hubs) ---------- */
.idx{display:grid;grid-template-columns:repeat(3,1fr);gap:0 clamp(20px,3vw,44px)}
.idx-col ul{list-style:none;margin:0 0 26px;padding:0}
.idx-col li{margin:0;border-bottom:1px dotted var(--line-strong)}
.idx-col li:last-child{border-bottom:0}
.idx-col a{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 2px;
  color:var(--char);text-decoration:none;font-weight:700;font-size:15.4px}
.idx-col a small{display:block;font-weight:500;color:var(--muted);font-size:13.6px;margin-top:2px}
.idx-col a:hover,.idx-col a:focus-visible{color:var(--red-ink)}
.idx-col a svg{width:13px;height:13px;fill:var(--red);flex:0 0 auto}
@media (max-width:980px){.idx{grid-template-columns:repeat(2,1fr)}}
@media (max-width:620px){.idx{grid-template-columns:1fr}}

/* ---------- council index on the NSW hub ---------- */
.council-idx{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}
.council-idx a{background:#fff;padding:15px 17px;text-decoration:none;color:var(--char);font-weight:700;font-size:15px;
  display:block}
.council-idx a span{display:block;font-weight:500;font-size:13.2px;color:var(--muted);margin-top:3px}
.council-idx a:hover,.council-idx a:focus-visible{background:var(--plaster-3);color:var(--red-ink)}
@media (max-width:1040px){.council-idx{grid-template-columns:repeat(3,1fr)}}
@media (max-width:760px){.council-idx{grid-template-columns:repeat(2,1fr)}}
@media (max-width:460px){.council-idx{grid-template-columns:1fr}}

/* ---------- prose block for policy pages ---------- */
.prose{max-width:76ch}
.prose h2{font-size:clamp(1.34rem,1.1rem + .9vw,1.76rem);margin-top:1.8em}
.prose h2:first-child{margin-top:0}
.prose h3{margin-top:1.5em}
.prose ul{padding-left:1.2em}

/* ---------- gallery ---------- */
.gal{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(14px,1.8vw,22px)}
.gal figure{margin:0;background:#fff;border:1px solid var(--line)}
.gal img{width:100%;aspect-ratio:4/3;object-fit:cover}
.gal figcaption{padding:14px 17px;font-size:14.6px;color:var(--muted);line-height:1.5;background:#fff}
.gal figcaption b{display:block;color:var(--char);font-size:15.4px;margin-bottom:3px}
@media (max-width:980px){.gal{grid-template-columns:repeat(2,1fr)}}
@media (max-width:600px){.gal{grid-template-columns:1fr}}

/* ---------- misc ---------- */
.two-col{columns:2;column-gap:clamp(24px,3vw,48px)}
.two-col li{break-inside:avoid}
@media (max-width:720px){.two-col{columns:1}}
.tight{margin-bottom:0}
.lede--sm{font-size:16.4px}
.sec--tight{padding-top:clamp(34px,4vw,58px);padding-bottom:clamp(34px,4vw,58px)}

/* ---------- dark-surface parallels ---------- */
.sec--ink .scope-col{background:var(--char-2);border-color:var(--ink-line);color:var(--ink-body)}
.sec--ink .scope-col h3{color:#fff}
.sec--ink .scope-col h3 svg{fill:#fff}
.sec--ink .scope-col--out h3 svg{fill:var(--red-lift)}
.sec--ink .scope-note{color:var(--ink-muted)}
.sec--ink .tbl-wrap{background:var(--char-2);border-color:var(--ink-line)}
.sec--ink table.tbl th{background:#000;color:#fff}
.sec--ink table.tbl td{color:var(--ink-body);border-top-color:var(--ink-line)}
.sec--ink table.tbl td:first-child{color:#fff}
.sec--ink table.tbl tbody tr:nth-child(even){background:rgba(255,255,255,.035)}
.sec--ink .lcard{background:var(--char-2);border-color:var(--ink-line);color:var(--ink-body)}
.sec--ink .lcard h3 a{color:#fff}
.sec--ink .lcard h3 a:hover,.sec--ink .lcard h3 a:focus-visible{color:var(--red-lift)}
.sec--ink .lcard p{color:var(--ink-muted)}
.sec--ink .lcard .go{color:var(--red-lift)}
.sec--ink .lfacts{background:var(--ink-line);border-color:var(--ink-line)}
.sec--ink .lfacts div{background:var(--char-2);color:var(--ink-body)}
.sec--ink .lfacts dt{color:var(--red-lift)}
.sec--ink .lfacts dd{color:#fff}
.sec--ink .nearby a{background:var(--char-2);border-color:var(--ink-line);color:#fff}
.sec--ink .nearby a:hover,.sec--ink .nearby a:focus-visible{border-color:var(--red-lift);color:var(--red-lift)}
.sec--ink .idx-col li{border-bottom-color:var(--ink-line)}
.sec--ink .idx-col a{color:#fff}
.sec--ink .idx-col a small{color:var(--ink-muted)}
.sec--ink .idx-col a:hover,.sec--ink .idx-col a:focus-visible{color:var(--red-lift)}
.sec--ink .council-idx{background:var(--ink-line);border-color:var(--ink-line)}
.sec--ink .council-idx a{background:var(--char-2);color:#fff}
.sec--ink .council-idx a span{color:var(--ink-muted)}
.sec--ink .council-idx a:hover,.sec--ink .council-idx a:focus-visible{background:#15171a;color:var(--red-lift)}
.sec--ink .gal figure{background:var(--char-2);border-color:var(--ink-line)}
.sec--ink .gal figcaption{background:var(--char-2);color:var(--ink-muted)}
.sec--ink .gal figcaption b{color:#fff}
.sec--ink .hero-pills li,.sec--ink .prose{color:var(--ink-body)}
.sec--ink a{color:var(--red-lift)}
.sec--ink a:hover,.sec--ink a:focus-visible{color:#fff}

/* The Quick Quote tab is fixed to the right edge on desktop. Wide tables are the one
   component whose text can run under it, so they keep a gutter clear of it. */
@media (min-width:1041px){
  .tbl-wrap{margin-right:56px}
}

/* ==========================================================================
   Theme neutrality for components the approved homepage only ever used on one
   background. Inner pages place them on both, so each needs a light-surface
   default and a dark-surface override rather than one hard-coded colour.
   ========================================================================== */

/* Triage was authored inside the homepage's charcoal band, so its heading was
   white and its list text was the dark-surface body colour. On a plaster band
   that is invisible. */
.sec:not(.sec--ink) .triage-col:first-child h3,
.sec:not(.sec--ink) .triage-col:last-child h3{color:var(--char)}
.sec:not(.sec--ink) .triage-col:first-child h3{border-bottom-color:#2F6B4C}
.sec:not(.sec--ink) .triage-col:first-child h3 svg{fill:#2F6B4C}
.sec:not(.sec--ink) .triage-col:last-child h3 svg{fill:var(--red-ink)}
.sec:not(.sec--ink) .triage-col li{color:var(--text)}
.sec:not(.sec--ink) .triage-col li::before{background:var(--line-strong)}

/* Small red type on charcoal sits at 3.45:1. The lifted red clears 4.5:1. */
.sec--ink .eyebrow--plain,.final .eyebrow--plain{color:var(--red-lift)}

/* Anything that inherits a light-surface muted or body colour needs the dark
   parallel when the band is charcoal. */
.sec--ink .lede,.sec--ink .factor p,.sec--ink .scope-note,.sec--ink .seq-step p,
.sec--ink .seq-k,.sec--ink .symp p,.sec--ink .area-note,.sec--ink .fam-lede,
.sec--ink .prep-link span,.sec--ink .work-note,.sec--ink .idx-col a small,
.sec--ink p,.sec--ink li,.sec--ink dd{color:var(--ink-body)}
.sec--ink .seq-k--note,.sec--ink b,.sec--ink strong,.sec--ink .fam-tag{color:#fff}
.sec--ink .seq-step h3,.sec--ink .factor h3,.sec--ink .tile h3{color:#fff}
.sec--ink .factor,.sec--ink .seq-step{border-color:var(--ink-line)}
.sec--ink .steps li::marker{color:var(--red-lift)}

/* ---------- full enquiry form (contact page) ---------- */
.efm{max-width:760px}
.efm .fld{margin-bottom:16px}
.efm label{display:block;font-size:13.4px;font-weight:800;margin-bottom:6px;color:var(--char)}
.efm .opt{font-weight:500;color:var(--muted)}
.efm input,.efm select,.efm textarea{
  width:100%;font-family:inherit;font-size:16px;color:var(--text);background:#fff;
  border:1.5px solid var(--line-mid,#9A9284);border-radius:8px;padding:12px 13px;line-height:1.4;min-height:48px;
}
.efm textarea{min-height:128px;resize:vertical}
.efm select{appearance:none;padding-right:38px;background-repeat:no-repeat;background-position:right 13px center;
  background-size:15px;background-image:url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'%3E%3Cpath fill='%235C6570' d='M8 11.2 2.8 6l1.1-1.1L8 9l4.1-4.1L13.2 6z'/%3E%3C/svg%3E")}
.efm input:focus,.efm select:focus,.efm textarea:focus{outline:3px solid var(--char);outline-offset:1px;border-color:var(--char)}
.efm-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.efm-send{
  margin-top:8px;background:var(--red-ink);color:#fff;border:2px solid var(--red-ink);
  font-family:inherit;font-weight:800;font-size:15.4px;padding:15px 30px;border-radius:9px;cursor:pointer;min-height:52px;
}
.efm-send:hover,.efm-send:focus-visible{background:var(--red);border-color:var(--red)}
.efm-send:focus-visible{outline:3px solid var(--char);outline-offset:2px}
.efm-note{font-size:13px;color:var(--muted);margin:14px 0 0}
@media (max-width:640px){.efm-row{grid-template-columns:1fr;gap:0}}
